INSERT INTO `attestations` (`id`,`form_id`,`source_id`,`date_label`,`year`,`witness`,`locator`,`excerpt`,`confidence`,`witness_type`,`repository`,`shelfmark`,`facsimile_url`,`directly_inspected`,`editorial_note`) VALUES
(86,30,181,'1694',1694,'The first edition of the Académie française dictionary prints DESASTRE as a headword and defines it as a disastrous accident or misfortune.','First edition, tome 1, printed page 61, Gallica leaf f89, right column','DESASTRE. s. m. Accident funeste, malheur.','established','printed_book','Bibliothèque de l’Institut de France; digitized by BnF Gallica','ark:/12148/bpt6k12803924, f. 89','https://gallica.bnf.fr/iiif/ark:/12148/bpt6k12803924/f89/full/full/0/native.jpg',1,'The Gallica page image was directly inspected. It verifies the unaccented 1694 French dictionary headword DESASTRE and its opening definition; it is not claimed as the earliest French or English occurrence.'),
(87,168,181,'1694',1694,'The first edition of the Académie française dictionary prints HOSTEL as a headword in the historical French family later normalized as hôtel.','First edition, tome 1, printed page 572, Gallica leaf f600, left column','HOSTEL. s. m. Grande maison d’un Prince...','established','printed_book','Bibliothèque de l’Institut de France; digitized by BnF Gallica','ark:/12148/bpt6k12803924, f. 600','https://gallica.bnf.fr/iiif/ark:/12148/bpt6k12803924/f600/full/full/0/native.jpg',1,'The Gallica page image was directly inspected. It verifies the historical dictionary form HOSTEL in 1694 within the French hotel family; it does not show the modern accented spelling hôtel and is not claimed as the earliest French or English occurrence.'),
(88,43,182,'1694',1694,'The PESTE entry in the first edition of the Académie française dictionary uses quarantaine for imposed isolation after travel from a place suspected of plague.','First edition, tome 2, printed page 225, Gallica leaf f233, right column, PESTE entry','on fait faire quarantaine à ceux qui viennent d’un lieu soupçonné de peste','established','printed_book','Bibliothèque de l’Institut de France; digitized by BnF Gallica','ark:/12148/bpt6k1280391q, f. 233','https://gallica.bnf.fr/iiif/ark:/12148/bpt6k1280391q/f233/full/full/0/native.jpg',1,'The Gallica page image was directly inspected. It verifies a 1694 contextual use of quarantaine for medical isolation inside the PESTE entry; it is not a QUARANTAINE headword and is not claimed as the earliest occurrence.'),
(89,22,182,'1694',1694,'The first edition of the Académie française dictionary prints SINCERE as a headword and opens with the senses true and frank.','First edition, tome 2, printed page 480, Gallica leaf f488, lower left column','SINCERE. adj. de t. g. Veritable, franc, qui est sans artifice, sans deguisement.','established','printed_book','Bibliothèque de l’Institut de France; digitized by BnF Gallica','ark:/12148/bpt6k1280391q, f. 488','https://gallica.bnf.fr/iiif/ark:/12148/bpt6k1280391q/f488/full/full/0/native.jpg',1,'The Gallica page image was directly inspected. It verifies the unaccented 1694 French dictionary headword SINCERE and its opening definition; it is not claimed as the earliest French or English occurrence.');
